import {question,choices,rand} from './math.mjs';
const app=document.querySelector('#app');let sound=false,ctx,mode=null,q,opts,round=0,correct=0,attempts=0,locked=false,selected=[],matched=[],pairs=[],timer=null,seconds=60,token=0,total=0,settings={limit:20,op:'mix'},bad=[];
try{total=Number(localStorage.getItem('toan-stars'))||0}catch{}updateStars();
const modes=[{id:'practice',icon:'🌱',title:'Vườn luyện tập',desc:'Từng bước nhỏ, tự tin lớn. Có gợi ý giúp bé!',tag:'THOẢI MÁI HỌC',color:'green',label:'Luyện tập'},{id:'bubble',icon:'🫧',title:'Bắt bong bóng',desc:'Tìm đáp án đúng, chạm và… bụp!',tag:'NHANH TAY · TINH MẮT',color:'blue',label:'Chơi ngay'},{id:'rocket',icon:'🚀',title:'Tên lửa vũ trụ',desc:'Giải phép tính, đưa tên lửa tới những vì sao.',tag:'THỬ THÁCH 60 GIÂY',color:'purple',label:'Cất cánh'},{id:'memory',icon:'🧩',title:'Lật thẻ thần kỳ',desc:'Ghép phép tính với đáp án. Thử tài trí nhớ!',tag:'GHI NHỚ · KHÁM PHÁ',color:'orange',label:'Lật thẻ'},{id:'mystery',icon:'🔎',title:'Số nào trốn mất?',desc:'Làm thám tử, tìm con số còn thiếu.',tag:'SUY LUẬN · TÌM TÒI',color:'pink',label:'Khám phá'}];
function updateStars(){document.querySelector('#stars').textContent='⭐ '+total}
function award(){total++;updateStars();try{localStorage.setItem('toan-stars',total)}catch{}}
function beep(win=true){if(!sound)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();[0,.12,.24].forEach((t,i)=>{let o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='sine';o.frequency.value=(win?520:220)*(1+i*.25);g.gain.setValueAtTime(.08,ctx.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+t+.2);o.start(ctx.currentTime+t);o.stop(ctx.currentTime+t+.2)})}catch{}}
document.querySelector('#sound').onclick=()=>{sound=!sound;document.querySelector('#sound').textContent=sound?'🔊':'🔇';document.querySelector('#sound').setAttribute('aria-label',sound?'Tắt âm thanh':'Bật âm thanh');if(sound)beep()};
document.querySelector('#brand').onclick=e=>{e.preventDefault();home()};
function burst(){const el=document.querySelector('#confetti');el.innerHTML=Array.from({length:24},(_,i)=>`<i style="--x:${rand(100)}vw;--r:${rand(360)}deg;--delay:${rand(200)}ms;background:${['#ffca58','#9b7bff','#5cceb0','#ff86ac'][i%4]}"></i>`).join('');setTimeout(()=>el.replaceChildren(),1700)}
function home(){token++;clearInterval(timer);mode=null;app.innerHTML=`<section class="welcome"><div><div class="eyebrow">XIN CHÀO, NHÀ THÁM HIỂM NHÍ!</div><h1>Hôm nay mình<br>chơi <span>toán</span> nhé<span class="spark">✦</span></h1><p>Chọn một trò chơi. Bắt đầu chuyến phiêu lưu!</p></div><div class="welcome-sticker" aria-hidden="true"><span>🌈</span><b>1 + 2 = <em>3</em></b><small>Thêm một chút giỏi mỗi ngày</small></div></section><section class="settings" aria-label="Chọn bài học"><span class="settings-title">🎯 Bé muốn học</span><div class="segments" id="op">${[['mix','Cộng & trừ'],['plus','Phép cộng'],['minus','Phép trừ']].map(([v,t])=>`<button data-value="${v}" class="${settings.op===v?'active':''}" aria-pressed="${settings.op===v}">${t}</button>`).join('')}</div><label>Phạm vi <select id="limit"><option value="10" ${settings.limit===10?'selected':''}>Đến 10</option><option value="20" ${settings.limit===20?'selected':''}>Đến 20</option></select></label></section><div class="section-head"><h2>Cả một đảo niềm vui</h2><span>5 cách chơi · Bé chọn nhé!</span></div><section class="cards">${modes.map((m,i)=>`<button class="game-card ${m.color} ${i===0?'featured':''}" data-mode="${m.id}"><div class="card-top"><span class="game-icon">${m.icon}</span><span class="card-num">0${i+1}</span></div><span class="tag">${m.tag}</span><h3>${m.title}</h3><p>${m.desc}</p><span class="card-cta">${m.label} <span>↗</span></span></button>`).join('')}<aside class="tip"><span>✨</span><h3>Mỗi lần thử là<br>một lần tiến bộ.</h3><p>Chơi một lượt nhỏ,<br>học thêm một điều hay.</p><div>+ &nbsp; − &nbsp; = &nbsp; ♡</div></aside></section>`;app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));app.querySelectorAll('#op button').forEach(b=>b.onclick=()=>{settings.op=b.dataset.value;home()});app.querySelector('#limit').onchange=e=>settings.limit=+e.target.value}
function start(id){token++;clearInterval(timer);mode=id;round=0;correct=0;attempts=0;seconds=60;locked=false;matched=[];selected=[];if(id==='memory'){let qs=[],answers=new Set();while(qs.length<4){let x=question(settings.limit,settings.op);if(!answers.has(x.answer)){answers.add(x.answer);qs.push(x)}}pairs=qs.flatMap((x,i)=>[{pair:i,text:`${x.a} ${x.sign} ${x.b}`,kind:'q'},{pair:i,text:''+x.answer,kind:'a'}]).sort(()=>Math.random()-.5);renderMemory()}else next();if(id==='rocket'){timer=setInterval(()=>{if(document.hidden)return;seconds--;let el=document.querySelector('#clock');if(el)el.textContent=seconds+'s';if(seconds<=0)finish()},1000)}}
function shell(body){const m=modes.find(x=>x.id===mode);app.innerHTML=`<div class="play-top"><button class="back" id="back">← Đảo trò chơi</button><span>${m.icon} ${m.title}</span><span>${mode==='rocket'?'<b id="clock">'+seconds+'s</b>':'⭐ '+correct}</span></div><section class="play ${m.color}">${body}</section>`;app.querySelector('#back').onclick=home;}
function next(){locked=false;bad=[];q=question(settings.limit,settings.op);opts=choices(mode==='mystery'?q.b:q.answer,settings.limit);renderQuestion()}
function renderQuestion(){const mystery=mode==='mystery',bubble=mode==='bubble',rocket=mode==='rocket';shell(`<div class="play-label">${rocket?'CHẠM TỚI NHỮNG VÌ SAO':`CÂU ${round+1} / ${mode==='practice'?10:8}`}</div>${rocket?`<div class="rocket-track"><span style="bottom:${Math.min(correct*7,80)}%">🚀</span><i>🌕</i></div>`:''}<h2>${mystery?'Số nào đang trốn nhỉ?':bubble?'Chạm bong bóng có đáp án đúng!':rocket?'Tiếp nhiên liệu cho tên lửa!':'Mình cùng tính nhé!'}</h2><div class="equation">${q.a} <span>${q.sign}</span> ${mystery?'<b class="unknown">?</b>':q.b} <span>=</span> ${mystery?q.answer:'<b class="unknown">?</b>'}</div><div class="answers ${bubble?'bubbles':''}">${opts.map((v,i)=>`<button data-answer="${v}" style="--i:${i}" ${bad.includes(v)?'disabled':''}>${v}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite">Chọn đáp án của bé ở phía trên nhé.</div>${mode==='practice'?'<button id="hint" class="hint">💡 Cho bé một gợi ý</button><div id="hint-content"></div>':''}<div class="progress" aria-label="Tiến độ"><div style="width:${rocket?Math.min(correct*10,100):round/(mode==='practice'?10:8)*100}%"></div></div>`);app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer,b));if(mode==='practice')app.querySelector('#hint').onclick=()=>{app.querySelector('#hint-content').innerHTML=`<p>${q.sign==='+'?`Có ${q.a} chấm, thêm ${q.b} chấm. Bé đếm tất cả nhé!`:`Có ${q.a} chấm, bớt ${q.b} chấm bị gạch. Còn bao nhiêu?`}</p><div class="dots">${Array.from({length:q.sign==='+'?q.a+q.b:q.a},(_,i)=>`<i class="${q.sign==='+'?(i>=q.a?'added':''):(i>=q.a-q.b?'removed':'')}"></i>`).join('')||'<b>Không có chấm nào: 0</b>'}</div>`}}
function answer(value,b){if(locked||bad.includes(value))return;attempts++;const expected=mode==='mystery'?q.b:q.answer;if(value!==expected){bad.push(value);b.disabled=true;b.classList.add('wrong');beep(false);document.querySelector('#feedback').textContent='Chưa đúng rồi. Bé thử một đáp án khác nhé!';return}locked=true;correct++;round++;award();beep();burst();b.classList.add('right');document.querySelector('#feedback').innerHTML=`<strong>${['Chính xác! Bé giỏi quá! 🌟','Tuyệt vời! Thêm một ngôi sao! ✨','Đúng rồi! Tiếp tục khám phá nhé! 🎉'][rand(3)]}</strong> <button class="next" id="next">Tiếp theo →</button>`;app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.querySelector('#next').onclick=()=>{if(mode!=='rocket'&&round>=(mode==='practice'?10:8))finish();else next()};if(mode==='rocket'){document.querySelector('#next').disabled=true;document.querySelector('#next').textContent='Bay tiếp! 🚀';let current=token;setTimeout(()=>{if(current===token&&mode==='rocket')next()},750)}}
function renderMemory(){shell(`<div class="play-label">GHÉP ĐÚNG ${matched.length} / 4 CẶP</div><h2>Phép tính tìm bạn</h2><p class="instructions">Lật 2 thẻ để ghép phép tính với đáp án của nó.</p><div class="memory-grid">${pairs.map((p,i)=>{let visible=selected.includes(i)||matched.includes(p.pair);return `<button class="memory-card ${visible?'flipped':''} ${matched.includes(p.pair)?'matched':''}" data-card="${i}" aria-label="${visible?p.text:'Thẻ úp '+(i+1)}" ${matched.includes(p.pair)?'disabled':''}>${visible?p.text:'✦'}</button>`}).join('')}</div><div id="feedback" role="status">${matched.length?'Giỏi lắm! Mình tìm tiếp nhé.':'Bé nhớ vị trí các thẻ nhé!'}</div>`);app.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>flip(+b.dataset.card))}
function flip(i){if(locked||selected.includes(i)||matched.includes(pairs[i].pair))return;selected.push(i);renderMemory();if(selected.length===2){locked=true;attempts++;const [a,b]=selected.map(j=>pairs[j]);let good=a.pair===b.pair&&a.kind!==b.kind,current=token;if(good){matched.push(a.pair);correct++;award();beep();burst()}else{document.querySelector('#feedback').textContent='Chưa thành đôi. Mình nhớ vị trí để thử lại nhé!'}setTimeout(()=>{if(current!==token)return;selected=[];locked=false;if(matched.length===4)finish();else renderMemory()},good?700:1200)}}
function finish(){token++;clearInterval(timer);locked=true;const id=mode;beep();burst();shell(`<div class="finish-icon">${correct?'🏆':'🌱'}</div><div class="play-label">HOÀN THÀNH MỘT CHUYẾN PHIÊU LƯU</div><h2>${correct?'Bé đã làm rất tốt!':'Mình cùng thử lại nhé!'}</h2><p class="instructions">${mode==='rocket'?'Hết 60 giây rồi! ':''}Mỗi lần luyện tập, bé lại giỏi hơn một chút.</p><div class="results"><div><b>⭐ ${correct}</b><span>Sao nhận được</span></div><div><b>${attempts?Math.round(correct/attempts*100):0}%</b><span>Lượt chọn đúng</span></div></div><p>Duỗi tay, nghỉ mắt một chút rồi chơi tiếp nhé 🌿</p><div class="finish-actions"><button class="primary" id="again">↻ Chơi thêm một lượt</button><button class="back" id="island">Chọn trò khác</button></div>`);document.querySelector('#again').onclick=()=>start(id);document.querySelector('#island').onclick=home;}
home();
